update public.products set description='Fresh bone-in goat meat with a combination of meat and bone, suitable for pepper soup, stews, soups, sauces and other Nigerian dishes where bone-in meat is preferred.', handling_protocols=array['Keep raw goat meat refrigerated or frozen and separate from ready-to-eat foods.','Avoid unnecessary washing or rinsing that can spread raw meat juices; clean hands, knives, boards and surfaces after handling.','For ordinary whole-muscle goat pieces, cook to at least 63°C / 145°F with a 3-minute rest.']::text[], storage_tips=array['Because the retail packs are portioned, refrigerate at 4°C or below and use within about 1–2 days.','For longer storage, freeze promptly at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Bone-In Goat Meat' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Fresh boneless goat meat with the bones removed, suitable for stews, soups, pepper soup, sauces, grilling and other goat-meat dishes.', handling_protocols=array['Keep cold and prevent raw meat juices from contacting ready-to-eat foods.','Clean hands and food-contact surfaces thoroughly after preparation.','For intact goat meat, cook to at least 63°C / 145°F with a 3-minute rest.']::text[], storage_tips=array['Because the retail packs are likely portioned, refrigerate at 4°C or below and use within about 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Boneless Goat Meat' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
